/**
 * Scoring / relevance / opportunity prompt logic — the shared "brain".
 *
 * Ported from apify-social-media-sdk/src/prompts.js (pure, no runtime deps).
 * Both surfaces consume this so they never drift:
 *  - the Claude Code plugin renders the static guidance into a Skill, and uses
 *    buildAutonomousDiscoveryPrompt() to assemble the per-run brief; and
 *  - the Chrome extension reuses the same relevance criteria / opportunity types
 *    / draft rules for its on-page scoring pass.
 *
 * Prompts emphasize read_page (accessibility tree) over screenshots for cost.
 */

/**
 * Build the autonomous discovery mode prompt for the agent.
 *
 * @param {Array<object>} products - Brands to promote (name, url, tagline, shortDescription, tags, aboutBrand)
 * @param {Array<object>} platforms - Detected platforms (name, homeUrl, hints, algorithmTips, isKnown)
 * @param {boolean} autoLike - Whether to auto-like relevant content
 * @param {number} maxTurns - Maximum turns available for this session
 * @param {number} engagementRatio - Ratio of general vs product-focused engagement (0.8 = 80% general)
 * @param {object} strategyWeights - { search, feed, trending } percentages summing to 100
 * @param {boolean} collectMemeIdeas - Whether to collect meme/parody opportunities
 * @param {Array<string>} seenUrls - Previously discovered URLs to skip
 * @param {string} voiceGuidance - User's voice-guidance markdown (rules + golden examples), '' when none
 * @returns {string} Complete prompt string for the agent
 */
export function buildAutonomousDiscoveryPrompt(products = [], platforms = [], autoLike = true, maxTurns = 100, engagementRatio = 0.8, strategyWeights = { search: 34, feed: 33, trending: 33 }, collectMemeIdeas = true, seenUrls = [], voiceGuidance = '') {
  // Format products section
  const productsSection = products.map((p, i) => `
### Product ${i + 1}: ${p.name}
- Website: ${p.url}
- Tagline: ${p.tagline}
- Description: ${p.shortDescription}
- Keywords: ${(p.tags || []).join(', ')}
- Brand Voice: ${p.aboutBrand || 'Helpful and professional'}
`).join('\n');

  // Format platforms section
  const platformsSection = platforms.map(p => {
    const hintsInfo = (p.hints || []).map(h => `  - ${h}`).join('\n');
    const algorithmInfo = (p.algorithmTips || []).length > 0
      ? `\n- Algorithm tips:\n${p.algorithmTips.map(t => `  - ${t}`).join('\n')}`
      : '';

    return `
### ${p.name} ${p.isKnown ? '' : '(Generic Platform)'}
- Home: ${p.homeUrl}
- Exploration tips:
${hintsInfo}${algorithmInfo}
`;
  }).join('\n');

  // Collect all unique tags for search suggestions
  const allTags = [...new Set(products.flatMap(p => p.tags || []))];
  const searchSuggestions = allTags.slice(0, 10).join(', ');

  // Like instruction based on setting
  const likeInstruction = autoLike
    ? `- Use like_content to like/upvote genuinely relevant content (be selective, not everything)`
    : `- DO NOT like or upvote anything - just observe and collect opportunities`;

  // Build strategy instructions based on weights
  const strategyInstructions = getStrategyInstructions(strategyWeights, searchSuggestions);

  // Build seen URLs section
  const seenUrlsSection = buildSeenUrlsSection(seenUrls);

  // User's accumulated voice feedback — overrides the generic draft rules.
  const voiceGuidanceSection = buildVoiceGuidanceSection(voiceGuidance);

  // Calculate engagement targets
  const productPercent = Math.round((1 - engagementRatio) * 100);
  const generalPercent = Math.round(engagementRatio * 100);

  // Meme section
  const memeSection = collectMemeIdeas ? `
### Meme/Parody Ideas
- **meme_post**: Something funny, relatable, or parody-worthy in the space
  - Note what's happening, why it's funny, and any meme format ideas
  - These will be sent to AI video maker for content creation
` : '';

  const perPlatformTurns = platforms.length > 0 ? Math.floor(maxTurns / platforms.length) : maxTurns;

  return `You are a social media manager building presence for brands in their industry spaces.

## TURN BUDGET
You have ${maxTurns} turns total for this session. Budget your exploration wisely.
- Each action (read_page, navigate, click, etc.) counts toward your budget
- Plan to spend roughly ${perPlatformTurns} turns per platform

## YOUR BRANDS
${productsSection}

## DETECTED PLATFORMS (you are logged in to these)
${platformsSection}

## YOUR ROLE
You're managing social media presence for these brands. Your goal is to find conversations worth joining that will grow the brand's presence and connect with the community.

Target balance: ~${productPercent}% product-focused, ~${generalPercent}% general industry conversations.

Use your judgment based on brand positioning to decide what's worth engaging with.

## DISCOVERY STRATEGY (Time Budget)
${strategyInstructions}
${seenUrlsSection}
## EXAMPLE OPPORTUNITY TYPES

These are examples - use your judgment to categorize or create your own types:

### Product Opportunities (~${productPercent}% of finds)
- **product_reply**: Reply where your product is directly relevant (someone asking for recommendations)
- **product_comment**: Nested reply where product solves someone's problem

### General Conversations (~${generalPercent}% of finds)
- **category_insight**: Industry discussion worth joining with your perspective
- **general_comment**: Conversation where adding value builds presence
- **original_post**: Idea for original content based on something trending
- **launch_comment**: A specific, non-promotional comment on a fresh Product Hunt launch in the brand's category (rare — at most one per run)
${memeSection}
Other types are welcome - use whatever makes sense for the situation.

## WHEN COLLECTING OPPORTUNITIES

### Relevance Scoring (Mental Checklist)
Before collecting any opportunity, mentally score it on these criteria (1-10 each):

1. **Product Fit**: Does this conversation relate to problems our product solves?
2. **Conversation Quality**: Is this an active, substantive discussion worth joining?
3. **Platform Appropriateness**: Are promotional contributions welcome in this context?
4. **Timing**: Is this conversation still active (< 24-48 hours old)?
5. **Conversation Potential**: Would a quality reply spark follow-up conversation?

**Only collect opportunities that score 6+ average**. Skip marginal opportunities.

### Required Fields
Use collect_opportunity with:
- **type**: Your categorization (use examples above or create your own)
- **title**: What it's about (first line of post/comment)
- **context**: Why this is interesting AND the angle you'll take. Include your mental relevance score (e.g., "Score: 8/10 - Direct question about automation tools")
- **platform**: Where you found it (Twitter, Reddit, etc.)
- **draftReply**: THE ACTUAL TEXT to post as a reply/comment (REQUIRED - this is the most important field!)
- **url**: The ACTUAL post/tweet/comment URL (NOT the feed or search URL). NEVER pass a feed URL like x.com/home or a search results URL. Find the direct link to the specific post.
- **suggestedAction**: Optional additional notes on approach, meme concepts, etc.

### Getting Accurate Post URLs (CRITICAL)
If you're on a feed page (x.com/home, reddit.com, etc.), you MUST find the actual post URL before collecting:
- **Twitter/X**: Each tweet has a timestamp link with format x.com/username/status/[id]. Look for it in the accessibility tree. If you can't find it, click into the tweet first.
- **Reddit**: Post URLs look like reddit.com/r/subreddit/comments/[id]/title. Usually visible as links in the accessibility tree.
- **Hacker News**: Use news.ycombinator.com/item?id=[id]
- **Product Hunt**: forum threads are producthunt.com/p/[category]/[slug]; launches are producthunt.com/products/[slug] — record the thread/launch URL, never the category listing.
- **LinkedIn**: Click into the post to get the full URL before collecting.
- If you can't determine the exact URL from the accessibility tree, **navigate to the post first** so the page URL is correct.

## DRAFT REPLY RULES

Voice: casual, opinionated, reactive. You react to things, you don't pontificate about them.
- 1-3 lines default, 4 lines absolute max. One strong sentence beats three mediocre ones.
- Match the energy: casual post → casual reply. Technical post → technical reply.

Avoid AI tells: no "Game changer", "Here's the thing...", "Let me be honest...", "The irony is...", "There's something about...", no hook→insight→lesson structure, no numbered wisdom, no motivational framing of mundane topics.

Never invent personal experiences — you're writing for a brand account. Don't write "I spent 2 weeks building..." or "I prototyped...". Reference the actual products above, or just react without claiming personal experience.

**BAD** (AI slop): "There's something about those early morning hours. No meetings. No Slack. Just you, the code, and the quiet hum of possibility."
**GOOD** (human): "3am debugging hits different. nothing like a mass of red errors to keep you humble"
${voiceGuidanceSection}
## NAVIGATION
Use **read_page** primarily (cheap). Use refs (e1, e2...) for click/type — more reliable than text matching.
For dynamic inputs (Reddit, Twitter): click input ref first, then use type_text (no ref needed).
${likeInstruction}

## RULES
- During discovery, only collect - posting happens later, once the user approves a reply
- Quality over quantity - find genuinely interesting opportunities
- Use read_page primarily, screenshots only when collecting opportunities

When done, say "COMPLETE" with a summary of what you found.
`;
}

/**
 * Get strategy-specific instructions based on percentage weights.
 */
export function getStrategyInstructions(weights, searchSuggestions) {
  const { search = 34, feed = 33, trending = 33 } = weights;

  const strategies = [];

  if (feed > 0) {
    strategies.push(`**Feed Browsing (${feed}% of time) — THIS IS YOUR PRIMARY STRATEGY**
- Reddit: Home feed first (your subscribed subreddits), then visit specific subreddits directly
- Twitter/X: For You feed, Following feed
- LinkedIn: Main feed
- Product Hunt: the forums (producthunt.com/forums → /p/general and other categories, 2-3 pages deep) — not the launch grid
- Scroll through what surfaces naturally — this is the safest and most human-like approach
- On Reddit especially: spend most time in your feed and subreddits, not searching`);
  }

  if (search > 0) {
    strategies.push(`**Keyword Search (${search}% of time)**
- Use platform search with keywords: ${searchSuggestions}
- Find specific communities and subreddits
- Look for questions and discussions about your product category

⚠️ SEARCH PACING (CRITICAL - avoids anti-bot detection):
- Do NOT search multiple keywords back-to-back rapidly
- Space out searches: browse/read content between each search query
- Maximum 2-3 searches per platform per session
- On Reddit: PREFER browsing your subscribed subreddits and home feed over searching
  - Go to reddit.com (home feed) first and scroll through what's there
  - Visit specific subreddits directly (r/SaaS, r/startups, etc.) instead of searching
  - Only use Reddit search sparingly (1-2 times max) when organic browsing hasn't surfaced enough
- On Product Hunt: use the forums' "Search all threads" box, not the product search
- On other platforms: alternate between feed browsing and search, never do consecutive searches`);
  }

  if (trending > 0) {
    strategies.push(`**Trending/Popular (${trending}% of time)**
- Twitter/X: Explore page, trending hashtags, viral tweets
- Reddit: r/all, r/popular, rising posts
- Look for viral moments, hot takes, industry buzz`);
  }

  return `Budget your time across these strategies:

${strategies.join('\n\n')}

Adjust your approach based on what's working - if one strategy yields better opportunities, lean into it.`;
}

/**
 * Build the seen URLs section for the discovery prompt.
 * Groups URLs by platform for easier scanning.
 */
export function buildSeenUrlsSection(seenUrls) {
  if (!seenUrls || seenUrls.length === 0) {
    return '';
  }

  const byPlatform = {};
  for (const url of seenUrls) {
    const platform = extractPlatformFromUrl(url);
    if (!byPlatform[platform]) byPlatform[platform] = [];
    byPlatform[platform].push(url);
  }

  let section = `\n## PREVIOUSLY DISCOVERED URLS (Skip These)\n`;
  section += `Found ${seenUrls.length} previously discovered posts. When you encounter these URLs, SKIP them and find new content:\n`;

  for (const [platform, urls] of Object.entries(byPlatform)) {
    section += `\n### ${platform} (${urls.length} posts)\n`;
    const displayUrls = urls.slice(0, 25);
    for (const url of displayUrls) {
      section += `- ${url}\n`;
    }
    if (urls.length > 25) {
      section += `- ... and ${urls.length - 25} more\n`;
    }
  }

  section += '\n';
  return section;
}

/**
 * Build the USER VOICE GUIDANCE section from the user's voice-guidance.md.
 * The file holds distilled voice rules + golden before/after examples of the
 * user's own rewrites; it outranks the generic Draft Reply Rules. Hard-capped
 * so an overgrown file can't blow the prompt budget.
 */
export function buildVoiceGuidanceSection(guidanceMarkdown, { maxChars = 6000 } = {}) {
  // Editing hints (HTML comments) are for the human reading the file, not the prompt.
  const md = (guidanceMarkdown || '').replace(/<!--[\s\S]*?-->/g, '').trim();
  if (!md) return '';

  let body = md;
  if (body.length > maxChars) {
    body = body.slice(0, maxChars) +
      '\n\n_(guidance truncated — ask Claude to distill voice-guidance.md via the review-notes skill)_';
  }

  return `
## USER VOICE GUIDANCE (highest priority)

The user wrote this from real feedback on past drafts. It reflects how THEY actually
sound. Where it conflicts with the generic Draft Reply Rules above, THIS WINS.
Match the register of its golden examples ("After" is the user's own writing).

${body}
`;
}

/**
 * Extract platform name from URL for grouping.
 */
export function extractPlatformFromUrl(url) {
  try {
    const parsed = new URL(url);
    const hostname = parsed.hostname.toLowerCase().replace(/^(www\.|old\.|m\.)/, '');

    if (hostname.includes('reddit')) return 'Reddit';
    if (hostname.includes('twitter') || hostname.includes('x.com')) return 'Twitter/X';
    if (hostname.includes('linkedin')) return 'LinkedIn';
    if (hostname.includes('facebook')) return 'Facebook';
    if (hostname.includes('instagram')) return 'Instagram';
    if (hostname.includes('youtube')) return 'YouTube';
    if (hostname.includes('ycombinator') || hostname.includes('hackernews')) return 'Hacker News';
    if (hostname.includes('producthunt')) return 'Product Hunt';
    if (hostname.includes('tiktok')) return 'TikTok';
    if (hostname.includes('discord')) return 'Discord';

    return hostname.split('.')[0].charAt(0).toUpperCase() + hostname.split('.')[0].slice(1);
  } catch {
    return 'Other';
  }
}

/**
 * Build the execute mode prompt for posting approved content (Pro / assisted posting).
 * @param {object} action - Approved action (opportunityId, url, action type, text)
 * @returns {string} Complete prompt string for the agent
 */
export function buildExecutePrompt(action = {}) {
  const url = action.url || '';
  const actionType = action.action || 'comment';
  const text = action.text || '';
  const opportunityId = action.opportunityId || '';

  let actionDesc;
  switch (actionType) {
    case 'comment':
      actionDesc = 'post a comment';
      break;
    case 'reply':
      actionDesc = 'reply to the post/comment';
      break;
    case 'post':
      actionDesc = 'create a new post';
      break;
    default:
      actionDesc = 'engage with the content';
  }

  return `You need to ${actionDesc} on a social media page.

TASK:
1. The browser is already at: ${url}
2. Find the appropriate input area and post this text:

---
${text}
---

HOW TO INTERACT:
1. Use read_page to get the accessibility tree with refs (e1, e2, etc.)
2. Find the input field (textbox, combobox) - look for refs like [ref=e5]
3. Use refs for reliable interaction:
   - type("e5", "your text") - type into input
   - click("e6") - click submit button
   - type_text("your text") - type into currently focused element (no ref needed)
4. If stuck, use screenshot(labels=true) to see visual ref badges

WORKFLOW (recommended for dynamic inputs like Reddit/Twitter):
\`\`\`
read_page → click("e5") (input ref) → type_text(text) → read_page again → click submit
\`\`\`

WHY: Some inputs (Reddit, Twitter) change their name/state after clicking, making refs stale.
After clicking an input, use type_text which types into whatever is focused - no ref needed.

After posting, verify it was submitted successfully.

When complete, respond with "SUCCESS" if the post was submitted.
If something goes wrong, respond with "FAILURE: [reason]".

Opportunity ID for reference: ${opportunityId}
`;
}
